.breakdance .evs-pg { background: var(--evs-bg); font-size: 14px; line-height: 20px; }
.breakdance .evs-pg.bde-section { padding: 0; }
.breakdance .evs-pg > .section-container { max-width: var(--evs-width); padding: 0 var(--evs-page); }
.breakdance .evs-pg h1, .breakdance .evs-pg h2, .breakdance .evs-pg h3 { font-family: var(--evs-font); margin: 0; color: var(--evs-text); text-wrap: balance; }
.breakdance .evs-pg .bde-div, .breakdance .evs-pg .bde-text, .breakdance .evs-pg .bde-shortcode, .breakdance .evs-pg .bde-button { min-width: 0; }
.breakdance .evs-pg :is(p, .breakdance a, .breakdance span, .breakdance div, .breakdance li, .breakdance button, .breakdance input, .breakdance select, .breakdance textarea, .breakdance b, .breakdance strong, .breakdance label) { font-family: var(--evs-font); }
/* Abschnittstitel wie SectionTitle/EvOpenSection: 20/800, über der Karte, ohne Strich */
.breakdance .evs-h2 { font-size: 20px !important; line-height: 1.25 !important; font-weight: 800 !important; letter-spacing: -.3px; }
.breakdance .evs-card { background: var(--evs-surface); border-radius: var(--evs-r-card); padding: 14px; box-sizing: border-box; width: 100%; }
.breakdance .evs-sechead { display: flex; flex-direction: row; align-items: baseline; justify-content: space-between; gap: 12px; width: 100%; }
.breakdance .evs-link .button-atom { all: unset; cursor: pointer; font-size: 13px; font-weight: 700; color: var(--evs-signal); white-space: nowrap; }
@media (min-width: 900px) {
  .breakdance .evs-pg { --evs-page: 32px; }
}

.breakdance .evx { position: relative; }
.breakdance .evx > .section-container { position: static; }
/* roter Block oben, das Bild ragt hinein (55 % der Bildhöhe), unten Radius 28 */
.breakdance .evx::before { content: ""; position: absolute; left: 0; right: 0; top: 0; z-index: 0; border-radius: 0 0 28px 28px; background: var(--evs-red);
  height: calc(16px + (min(100vw, var(--evs-width)) - 2 * var(--evs-page)) * .309); }

/* Raster: Handy eine Spalte in App-Reihenfolge; ab 900 px Tickets/Leiste rechts (klebt) */
.breakdance .evx-grid { position: relative; z-index: 1; display: grid; grid-template-columns: minmax(0, 1fr); gap: 0; padding: 16px 0 120px; width: 100%; }
.breakdance .evx-grid > * { margin-top: 22px; }
.breakdance .evx-grid > .evx-mediabox { margin-top: 0; }
.breakdance .evx-grid > .evs-facts, .breakdance .evx-grid > .evs-pills, .breakdance .evx-grid > .evs-invite { margin-top: 14px; }
.breakdance .evx-grid > .bde-shortcode:not(:has(*)) { display: none; }
.breakdance .evx-aside { display: contents; }
.breakdance .evx-aside > .evx-tbox { margin-top: 22px; }

/* Bild 16:9, Radius 20, Schatten; andere Formate ganz zeigen, Ränder unscharf (EvLetterbox) */
.breakdance .evx-mediabox { position: relative; width: 100%; aspect-ratio: 16 / 9; border-radius: var(--evs-r-card); overflow: hidden; background: #1B1D29;
  box-shadow: 0 10px 24px rgba(0,0,0,.18); }
.breakdance .evx-mediablur { position: absolute !important; inset: -16px; width: calc(100% + 32px) !important; height: calc(100% + 32px) !important; max-width: none !important;
  object-fit: cover; filter: blur(16px) brightness(.75); }
.breakdance .evx-media { position: relative; display: block; width: 100% !important; height: 100% !important; object-fit: contain; }

/* Kopf: Sparte, Titel + Herz, „von Veranstalter“ */
.breakdance .evx-head { display: grid; gap: 10px; width: 100%; }
.breakdance .evx-pill { width: fit-content; padding: 3px 8px; border-radius: 6px; background: var(--evs-signal); color: #fff;
  font-size: 11px; line-height: 16px; font-weight: 600; letter-spacing: .4px; text-transform: uppercase; }
.breakdance .evx-pill a { color: inherit; text-decoration: none; }
.breakdance .evx-titlerow { display: flex; flex-direction: row; align-items: flex-start; gap: 10px; width: 100%; }
.breakdance .evx-titlerow > .bde-shortcode { flex: none; width: auto; }
.breakdance .evx-title { flex: 1 1 0; min-width: 0; font-size: 23px !important; line-height: 1.2 !important; font-weight: 800 !important; letter-spacing: -.4px; overflow-wrap: anywhere; }
.breakdance .evx-titlerow .evs-save { width: 36px !important; height: 36px !important; margin: -4px -6px 0 0; }
.breakdance .evx-titlerow .evs-save svg { width: 22px; height: 22px; }
.breakdance .tix-evorg { display: inline-flex; gap: 8px; align-items: center; font-size: 14px; color: var(--evs-body); text-decoration: none; width: fit-content; }
.breakdance .tix-evorg__logo { width: 26px; height: 26px; border-radius: 50%; overflow: hidden; display: grid; place-items: center; flex: none;
  background: var(--evs-night); color: #fff; font-size: 11px; font-weight: 700; }
.breakdance .tix-evorg__logo img { width: 100%; height: 100%; object-fit: cover; }
.breakdance .tix-evorg__name { color: var(--evs-body); }
.breakdance .tix-evorg__name b { color: var(--evs-text); font-weight: 800; }
.breakdance .tix-evorg__chev { color: var(--evs-body); }

/* Fakten-Karte: rote Datums-Kachel + Datum/Countdown, Uhrzeit, Einlass, Ort (→ Karte), Adresse */
.breakdance .evs-facts { display: flex; flex-direction: row; gap: 12px; align-items: flex-start; padding: 12px; background: var(--evs-surface); border-radius: var(--evs-r-card); width: 100%; box-sizing: border-box; }
.breakdance .evs-dtile { flex: none; width: 58px; height: 66px; display: flex; flex-direction: column; align-items: center; justify-content: center;
  border-radius: var(--evs-r); background: var(--evs-red); line-height: 1.1; text-align: center; }
.breakdance .evs-dtile .bde-text { color: #fff; }
.breakdance .evs-dtile__wd { font-size: 11px; font-weight: 600; color: rgba(255,255,255,.85) !important; }
.breakdance .evs-dtile__d { font-size: 24px; font-weight: 800; line-height: 1.15; }
.breakdance .evs-dtile__m { font-size: 11px; font-weight: 800; }
.breakdance .evs-facts__b { flex: 1; min-width: 0; display: grid; gap: 2px; font-size: 12.5px; line-height: 1.4; color: var(--evs-body); }
.breakdance .evs-facts__top { display: flex; flex-direction: row; flex-wrap: wrap; align-items: center; gap: 4px 8px; }
.breakdance .evs-cd { padding: 1px 8px; border-radius: 100px; font-size: 11px; line-height: 16px; font-weight: 800; color: var(--evs-signal); background: rgba(232,68,90,.12); }
.breakdance .evs-cd--live { color: var(--evs-green); background: rgba(31,143,95,.12); }
.breakdance .evs-facts__t { font-size: 15.5px; line-height: 1.35; font-weight: 800; color: var(--evs-text); }
.breakdance .evs-facts__place, .breakdance .evs-facts__addr { width: 100%; }
.breakdance .evs-facts__place .button-atom, .breakdance .evs-facts__addr .button-atom { all: unset; box-sizing: border-box; display: flex; align-items: center; gap: 4px; width: 100%; cursor: pointer; }
.breakdance .evs-facts__place { margin-top: 4px; --ico-nav: url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHZpZXdCb3g9IjAgMCAyNCAyNCIgZmlsbD0ibm9uZSIgc3Ryb2tlPSIjMDAwIiBzdHJva2Utd2lkdGg9IjIiIHN0cm9rZS1saW5lY2FwPSJyb3VuZCIgc3Ryb2tlLWxpbmVqb2luPSJyb3VuZCI+PHBvbHlnb24gcG9pbnRzPSIzIDExIDIyIDIgMTMgMjEgMTEgMTMgMyAxMSIvPjwvc3ZnPg=="); }
.breakdance .evs-facts__place .button-atom { color: var(--evs-text); font-size: 14px; font-weight: 700; }
.breakdance .evs-facts__place .button-atom__text { flex: 1; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.breakdance .evs-facts__place .button-atom::before { content: ""; flex: none; width: 15px; height: 15px; background: var(--evs-signal); -webkit-mask: var(--ico) center / contain no-repeat; mask: var(--ico) center / contain no-repeat; }
.breakdance .evs-facts__place .button-atom::after { content: ""; flex: none; width: 15px; height: 15px; background: var(--evs-body);
  -webkit-mask: var(--ico-nav) center / contain no-repeat; mask: var(--ico-nav) center / contain no-repeat; }
.breakdance .evs-facts__addr .button-atom { padding-left: 19px; color: var(--evs-body); font-size: 12.5px; text-decoration: underline; text-decoration-color: rgba(107,111,130,.6); text-underline-offset: 2px; }
.breakdance .evs-facts__addr .button-atom__text { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

/* Pillen-Zeile (eine Zeile, waagerecht scrollbar): erste gefüllt, die übrigen ruhig (weiß, farbiges Icon) */
.breakdance .evs-pills { display: flex; flex-direction: row; flex-wrap: nowrap; gap: 8px; width: auto; overflow-x: auto; scrollbar-width: none;
  margin-left: calc(-1 * var(--evs-page)); margin-right: calc(-1 * var(--evs-page)); padding: 0 var(--evs-page); }
.breakdance .evs-pills::-webkit-scrollbar { display: none; }
.breakdance .evs-pill { flex: none; display: inline-flex; align-items: center; gap: 6px; padding: 6px 12px 6px 10px; border-radius: 100px; font-size: 12.5px; line-height: 18px; font-weight: 700;
  white-space: nowrap; width: auto; background: var(--evs-surface); color: var(--evs-text); }
.breakdance .evs-pill::before { content: ""; flex: none; width: 15px; height: 15px; background: currentColor; -webkit-mask: var(--ico) center / contain no-repeat; mask: var(--ico) center / contain no-repeat; }
.breakdance .evs-pill--red { color: #fff; background: var(--evs-signal); }
.breakdance .evs-pill--green { color: #fff; background: var(--evs-green); }
.breakdance .evs-pill--orange::before { background: var(--evs-orange); }
.breakdance .evs-pill--blue::before { background: var(--evs-blue); }
.breakdance .evs-pill--night::before { background: var(--evs-night); }

/* „Wer kommt mit?“ */
.breakdance .evs-invite { display: flex; flex-direction: row; align-items: center; gap: 12px; padding: 14px; background: var(--evs-surface); border-radius: var(--evs-r-card); width: 100%; box-sizing: border-box; }
.breakdance .evs-invite__dots { position: relative; z-index: 0; isolation: isolate; flex: none; width: 36px; height: 36px; margin-left: 40px; border-radius: 50%; background: var(--evs-blue);
  border: 2px solid #fff; color: #fff; font-size: 22px; font-weight: 600; line-height: 31px; text-align: center; box-sizing: border-box; }
.breakdance .evs-invite__dots::before, .breakdance .evs-invite__dots::after { content: ""; position: absolute; top: -2px; width: 36px; height: 36px; border-radius: 50%; border: 2px solid #fff; box-sizing: border-box; }
.breakdance .evs-invite__dots::before { left: -42px; background: var(--evs-signal); z-index: -2; }
.breakdance .evs-invite__dots::after { left: -22px; background: var(--evs-orange); z-index: -1; }
.breakdance .evs-invite__txt { flex: 1; display: grid; gap: 1px; }
.breakdance .evs-invite__t { font-size: 14px; font-weight: 800; color: var(--evs-text); }
.breakdance .evs-invite__s { font-size: 12.5px; color: var(--evs-body); }
.breakdance .evs-invite__btn .button-atom { all: unset; cursor: pointer; padding: 8px 12px; border-radius: 100px; background: var(--evs-signal); color: #fff; font-size: 12.5px; font-weight: 800; white-space: nowrap; }

/* Abschnitte (EvOpenSection): Titel über weißer Karte */
.breakdance .evx-sec { display: grid; gap: 10px; width: 100%; }
.breakdance .evx-text p { margin: 0 0 10px; font-size: 14px; line-height: 20px; color: var(--evs-text); }
.breakdance .evx-text p:last-child { margin-bottom: 0; }
.breakdance .evs-clamp.is-clamped { max-height: 150px; overflow: hidden; -webkit-mask: linear-gradient(#000 60%, transparent); mask: linear-gradient(#000 60%, transparent); }
.breakdance .evs-clamp__btn { display: inline-flex; align-items: center; gap: 4px; margin-top: 8px; padding: 0; border: 0; background: none; cursor: pointer; color: var(--evs-signal); font-size: 12.5px; font-weight: 700; }
.breakdance .evs-clamp__btn::after { content: ""; width: 14px; height: 14px; background: currentColor; -webkit-mask: url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHZpZXdCb3g9IjAgMCAyNCAyNCIgZmlsbD0ibm9uZSIgc3Ryb2tlPSIjMDAwIiBzdHJva2Utd2lkdGg9IjIiIHN0cm9rZS1saW5lY2FwPSJyb3VuZCIgc3Ryb2tlLWxpbmVqb2luPSJyb3VuZCI+PHBhdGggZD0ibTYgOSA2IDYgNi02Ii8+PC9zdmc+") center / contain no-repeat; mask: url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHZpZXdCb3g9IjAgMCAyNCAyNCIgZmlsbD0ibm9uZSIgc3Ryb2tlPSIjMDAwIiBzdHJva2Utd2lkdGg9IjIiIHN0cm9rZS1saW5lY2FwPSJyb3VuZCIgc3Ryb2tlLWxpbmVqb2luPSJyb3VuZCI+PHBhdGggZD0ibTYgOSA2IDYgNi02Ii8+PC9zdmc+") center / contain no-repeat; }
.breakdance .evs-clamp__btn.is-open::after { transform: rotate(180deg); }

/* Zeilen mit Icon im getönten Kreis (EvOpenRow): Gut zu wissen, Anfahrt */
.breakdance .evx-list { padding-top: 2px; padding-bottom: 2px; }
.breakdance .evx-list p { position: relative; margin: 0; padding: 12px 0 12px 36px; font-size: 14px; line-height: 20px; }
.breakdance .evx-list p::before { content: ""; position: absolute; left: 0; top: 10px; width: 24px; height: 24px; border-radius: 50%; background: var(--evs-tint); }
.breakdance .evx-list p::after { content: ""; position: absolute; left: 5.5px; top: 15.5px; width: 13px; height: 13px; background: var(--evs-signal);
  -webkit-mask: var(--ico) center / contain no-repeat; mask: var(--ico) center / contain no-repeat; }
.breakdance .evx-list p + p { background: linear-gradient(var(--evs-rowline), var(--evs-rowline)) right top / calc(100% - 36px) 1px no-repeat; }
.breakdance .evx-row { position: relative; display: grid; grid-template-columns: 1fr auto; column-gap: 12px; width: 100%; padding: 12px 0 12px 36px; box-sizing: border-box; }
.breakdance .evx-row::before { content: ""; position: absolute; left: 0; top: 10px; width: 24px; height: 24px; border-radius: 50%; background: var(--evs-tint); }
.breakdance .evx-row::after { content: ""; position: absolute; left: 5.5px; top: 15.5px; width: 13px; height: 13px; background: var(--evs-signal);
  -webkit-mask: var(--ico) center / contain no-repeat; mask: var(--ico) center / contain no-repeat; }
.breakdance .evx-row + .evx-row { background: linear-gradient(var(--evs-rowline), var(--evs-rowline)) right top / calc(100% - 36px) 1px no-repeat; }
.breakdance .evx-row > .bde-text { grid-column: 1; }
.breakdance .evx-row > .bde-button { grid-column: 2; grid-row: 1 / span 2; align-self: start; }
.breakdance .evx-row-b { font-size: 14px; line-height: 20px; font-weight: 600; }
.breakdance .evx-row-s { font-size: 12.5px; color: var(--evs-body); }
.breakdance .evx-act .button-atom { all: unset; cursor: pointer; color: var(--evs-signal); font-size: 12.5px; line-height: 20px; }
.breakdance .evx-act .button-atom::after { content: " ›"; }
.breakdance .evx-route { padding-top: 2px; padding-bottom: 14px; }
.breakdance .evx-routes { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; width: 100%; margin-top: 4px; }
.breakdance .evx-routes .bde-button { width: 100%; }
.breakdance .evx-routes .button-atom { all: unset; box-sizing: border-box; cursor: pointer; width: 100%; display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 12px 4px;
  border-radius: var(--evs-r); background: rgba(232,68,90,.08); color: var(--evs-text); font-size: 11px; font-weight: 700; text-align: center; }
.breakdance .evx-routes .button-atom::before { content: ""; width: 20px; height: 20px; background: var(--evs-signal); -webkit-mask: var(--ico) center / contain no-repeat; mask: var(--ico) center / contain no-repeat; }

/* Tixomat-Bausteine (Programm, FAQ, Galerie, Video, Gewinnspiel, Projekt, Termine) im App-Look */
.breakdance .evx { --tix-primary: var(--evs-night); --tix-font-body: var(--evs-font); --ep-border: var(--evs-sep); --ep-radius: var(--evs-r); --ep-text: var(--evs-text);
  --ep-muted: var(--evs-body); --ep-bg: var(--evs-surface); --tix-faq-border: transparent; --tix-faq-divider: var(--evs-rowline); --tix-faq-radius: 0;
  --tix-faq-max-width: none; --tix-text: var(--evs-text); --tix-raffle-header-bg: var(--evs-tint); --tix-raffle-header-color: var(--evs-text);
  --tix-btn1-bg: var(--evs-night); --tix-btn1-color: #fff; --tix-btn1-hover-bg: var(--evs-night); --tix-btn1-hover-color: #fff; --tix-btn1-radius: var(--evs-r); }
.breakdance .evx-sec .tix-tt, .breakdance .evx-sec .tix-faq, .breakdance .evx-sec .tix-raffle { width: 100%; }
.breakdance .evx .tix-tt-day, .breakdance .evx .tix-tt-filter-btn { border-radius: 999px !important; font-weight: 700 !important; box-shadow: none !important; }
.breakdance .evx .tix-tt-day.active, .breakdance .evx .tix-tt-filter-btn.active { background: var(--evs-night) !important; border-color: var(--evs-night) !important; color: #fff !important; }
.breakdance .evx .tix-tt-list-item, .breakdance .evx .tix-tt-slot { border-radius: var(--evs-r) !important; }
.breakdance .evx .tix-tt-tba { background: none; border: 0; padding: 0; margin: 0 0 8px; text-align: left; color: var(--evs-body); font-size: 12.5px; }
/* FAQ: Zeilen in der Karte, „+“ im getönten Kreis, offen rot gefüllt als „×“ */
.breakdance .evx .tix-faq-item { border: 0 !important; border-radius: 0 !important; box-shadow: none !important; background: none !important; margin: 0 !important; }
.breakdance .evx .tix-faq-item + .tix-faq-item { border-top: 1px solid var(--evs-rowline) !important; }
.breakdance .evx .tix-faq-question { padding: 12px 0 !important; background: none !important; gap: 12px; }
.breakdance .evx .tix-faq-q-text { font-size: 14px; font-weight: 700; color: var(--evs-text); }
.breakdance .evx .tix-faq-icon { width: 26px; height: 26px; flex: none; border-radius: 50%; display: grid; place-items: center; background: var(--evs-tint); color: var(--evs-signal); transition: transform .2s, background .2s; }
.breakdance .evx .tix-faq-icon svg { display: none; }
.breakdance .evx .tix-faq-icon::before { content: "+"; font-size: 18px; font-weight: 600; line-height: 1; }
.breakdance .evx .tix-faq-question[aria-expanded="true"] .tix-faq-icon { background: var(--evs-signal); color: #fff; transform: rotate(45deg); }
.breakdance .evx .tix-faq-a-inner, .breakdance .evx .tix-faq-a-inner p { font-size: 13.5px; line-height: 1.5; color: var(--evs-body); }
.breakdance .tix-gal { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; width: 100%; }
.breakdance .tix-gal__item { display: block; aspect-ratio: 1; border-radius: var(--evs-r); overflow: hidden; background: var(--evs-sep); }
.breakdance .tix-gal__item img { width: 100%; height: 100%; object-fit: cover; display: block; }
.breakdance .tix-video { position: relative; width: 100%; aspect-ratio: 16 / 9; border-radius: var(--evs-r); overflow: hidden; background: #000; }
.breakdance .tix-video iframe, .breakdance .tix-video video { position: absolute; inset: 0; width: 100%; height: 100%; border: 0; }
.breakdance .tix-charity { display: flex; gap: 12px; align-items: center; }
.breakdance .tix-charity__img { width: 56px; height: 56px; border-radius: var(--evs-r); object-fit: cover; flex: none; }
.breakdance .tix-charity__t { display: grid; gap: 2px; font-size: 14px; line-height: 1.45; }
.breakdance .tix-charity__t b { font-weight: 700; }
.breakdance .tix-charity__t span { color: var(--evs-body); font-size: 12.5px; }
.breakdance .tix-series { display: grid; }
.breakdance .tix-series__row { display: flex; justify-content: space-between; gap: 12px; padding: 12px 0; color: var(--evs-text); text-decoration: none; font-size: 14px; }
.breakdance .tix-series__row + .tix-series__row { border-top: 1px solid var(--evs-rowline); }
.breakdance .tix-series__act { color: var(--evs-signal); font-weight: 700; font-size: 12.5px; white-space: nowrap; }
.breakdance .evx-sec .tix-raffle { border: 0; border-radius: var(--evs-r); box-shadow: none; overflow: hidden; }

/* Tickets: Titel + „inkl. MwSt.“, Auswahl wie die Ticketauswahl der App */
.breakdance .evx-mwst { font-size: 11px; color: var(--evs-body); }
.breakdance .evx-tbox { scroll-margin-top: 90px; }
.breakdance .evx-tbox .tix-sel-cat { border-radius: 0 !important; border: 0 !important; box-shadow: none !important; background: none !important; padding-left: 0 !important; padding-right: 0 !important; }
.breakdance .evx-tbox .tix-sel-cat + .tix-sel-cat { border-top: 1px solid var(--evs-rowline) !important; }
.breakdance .evx-tbox .tix-sel-cat-name { font-weight: 800 !important; color: var(--evs-text) !important; }
.breakdance .evx-tbox .tix-sel-btn { background: var(--evs-night) !important; border-color: var(--evs-night) !important; color: #fff !important; border-radius: 50% !important; }
.breakdance .evx-tbox .tix-sel-btn:disabled { background: transparent !important; border-color: transparent !important; color: var(--evs-muted) !important; opacity: 1; }
.breakdance .evx-tbox .tix-sel-buy { background: var(--evs-night) !important; color: #fff !important; border: 0 !important; border-radius: var(--evs-r) !important; min-height: 50px; font-weight: 600 !important; box-shadow: none !important; }
.breakdance .evx-tbox .tix-sel-buy:disabled { background: #9396A5 !important; color: #fff !important; opacity: 1; }
.breakdance .evx-tbox .tix-sel-coupon-code { border-radius: var(--evs-r) !important; border-color: var(--evs-sep) !important; }
.breakdance .evx-tbox .tix-sel-coupon-btn { border-radius: var(--evs-r) !important; background: #fff !important; color: var(--evs-night) !important; border: 1px solid var(--evs-muted) !important; font-weight: 600 !important; }
.breakdance .evx-tbox .tix-sel-group-discount, .breakdance .evx-tbox .tix-group-btn { border-radius: var(--evs-r) !important; }
.breakdance .evx-tbox .tix-sel-total-price { font-weight: 800 !important; color: var(--evs-text) !important; }

/* Leiste unten (EvFloatingBar): schwebende weiße Karte, Radius 24 */
.breakdance .evs-bar { position: fixed !important; left: 16px; right: 16px; bottom: calc(16px + env(safe-area-inset-bottom, 0px)); z-index: 60; margin: 0 !important;
  background: var(--evs-surface); border-radius: 24px; padding: 10px; box-shadow: 0 8px 24px rgba(0,0,0,.10); box-sizing: border-box; width: auto; }
.breakdance .evs-bar__buy { display: flex; flex-direction: row; align-items: center; gap: 12px; width: 100%; }
.breakdance .evs-bar__price { flex: 1; display: grid; padding-left: 8px; }
.breakdance .evs-bar__l { font-size: 11px; color: var(--evs-body); line-height: 1.3; }
.breakdance .evs-bar__p { font-size: 20px; font-weight: 800; line-height: 1.2; color: var(--evs-text); }
.breakdance .evs-bar .bde-button { width: auto; }
.breakdance .evs-bar__btn .button-atom, .breakdance .evs-bar__state .button-atom { all: unset; box-sizing: border-box; cursor: pointer; display: flex; align-items: center; justify-content: center; gap: 8px;
  height: 50px; padding: 0 18px; min-width: 196px; border-radius: var(--evs-r); background: var(--evs-night); color: #fff; font-size: 15px; font-weight: 600; }
.breakdance .evs-bar__btn .button-atom::before { content: ""; width: 20px; height: 20px; background: currentColor; -webkit-mask: var(--ico) center / contain no-repeat; mask: var(--ico) center / contain no-repeat; }
.breakdance .evs-bar__wide, .breakdance .evs-bar__wide .button-atom { width: 100% !important; }
.breakdance .evs-bar__state .button-atom { background: #9396A5; cursor: default; }
.breakdance .evs-bar__free { display: flex; flex-direction: row; align-items: center; gap: 12px; padding: 4px 4px 8px; width: 100%; }
.breakdance .evs-bar__ic { flex: none; width: 36px; height: 36px; border-radius: 50%; background: rgba(31,143,95,.12); position: relative; }
.breakdance .evs-bar__ic::after { content: ""; position: absolute; inset: 9px; background: var(--evs-green); -webkit-mask: var(--ico) center / contain no-repeat; mask: var(--ico) center / contain no-repeat; }
.breakdance .evs-bar__ft { font-size: 16px; font-weight: 800; color: var(--evs-green); }
.breakdance .evs-bar__fs { font-size: 12.5px; color: var(--evs-body); }

@media (min-width: 900px) {
  .breakdance .evx::before { height: 260px; }
  .breakdance .evx-grid { grid-template-columns: minmax(0, 1fr) 380px; column-gap: 32px; padding: 32px 0 64px; align-items: start; }
  .breakdance .evx-grid > * { grid-column: 1; }
  .breakdance .evx-aside { display: grid; gap: 22px; grid-column: 2 !important; grid-row: 1 / span 40; align-self: start; position: sticky; top: 88px; margin-top: 0 !important; }
  .breakdance .evx-aside > .evx-tbox { margin-top: 0; background: var(--evs-surface); border-radius: var(--evs-r-card); padding: 16px 14px 4px; gap: 4px; }
  .breakdance .evx-aside > .evx-tbox > .evs-card { padding: 0; }
  .breakdance .evx-aside:has(.evx-tbox) .evs-bar { display: none; }
  .breakdance .evs-bar { position: static !important; box-shadow: none; padding: 14px; border-radius: var(--evs-r-card); }
  .breakdance .evs-bar__btn .button-atom { min-width: 0; }
  .breakdance .evx-title { font-size: 34px !important; }
  .breakdance .evs-pills { flex-wrap: wrap; overflow: visible; margin-left: 0; margin-right: 0; padding: 0; }
}
